def count_bidirectional(tuples):
    # Create a dictionary to store the counts of each tuple
    count_dict = {}

    # Populate the dictionary with the counts of each tuple
    for t in tuples:
        if t in count_dict:
            count_dict[t] += 1
        else:
            count_dict[t] = 1

    # Initialize a set to store the bidirectional pairs
    bidirectional_pairs = set()

    # Iterate through the dictionary to find bidirectional pairs
    for t in count_dict:
        reverse_t = (t[1], t[0])
        if t == reverse_t:
            if count_dict[t] > 1:
